    biography: "Marc Wesselink is a Venture Partner at Contrarian Ventures, based in the Netherlands. His firm bio describes him as a serial entrepreneur who started 12 companies between 1994 and 2008 and invested in over 150 between 2004 and 2018. He co-founded Hapgids, which evolved into Just-Eat.com, and iChoosr, a green energy group-buying platform operating in six countries. He co-founded the Dutch and African Startupbootcamp programmes, which grew into a global accelerator with over 900 portfolio companies, and founded Venturerock in 2018. Contrarian's bio references a 2016 start with the firm, which predates the firm's stated 2017 founding, so his join year is left null here. His education is not published.",
