    biography: "Avi Zeevi is Co-founder and General Partner of Viola Ventures and a co-founder of the Viola Group. He co-founded and led MINT Technologies, which merged into Oshap Technologies, where he served as CFO through its 1999 sale to SunGard for $220 million. He was the first venture investor in Actimize and served as its active Chairman from 2001 until its 2007 sale to NICE Systems for $280 million. According to Viola, he led both Payoneer and Pagaya from seed to IPO and serves as Chairman of both. He sits on boards including Payoneer, Personetics, EverC, Sorbet, Duetti and Pagaya, and lectures on venture capital in the Kellogg-Recanati International Executive MBA program.",
