    biography: "Arjuna Costa is a Co-Founder and Managing Partner of Flourish Ventures, focused on venture investing across emerging markets in Asia, Africa and Latin America. Before Flourish he was a Partner at Omidyar Network, where he built a portfolio of early-stage inclusive fintech companies, and he previously worked at the Bill & Melinda Gates Foundation on mobile money and at The Rohatyn Group investing equity and debt in emerging-markets consumer finance. In 2003 he co-founded a $120 million private equity fund to turn around distressed commercial banks in Africa, and earlier he spent five years at Lehman Brothers financing power plants and airports. Flourish lists his current investments including Akua, Albo, Kamino, Liquid, Neon, Paga, Revena, StepChange and TapTap Send, and exited investments including Guiabolso, Juntos, Segovia and Zoona. He holds an MBA from Harvard Business School and a BA in Computer Science from Columbia University.",
