    biography: "Diana Narváez is a Principal at Flourish Ventures and the firm's primary Latin America investor, working with founding teams at fintechs including Kamino, Heru, Neon and Swap. She previously led strategy and business development at Picap, a Colombian motorcycle ride-hailing and logistics startup, and co-founded Impulsum Capital, an impact investing vehicle for Colombian family offices. Earlier she was a consultant at McKinsey in Mexico and worked at JPMorgan in Brazil. She was part of the co-founding team of the Diversity VC LatAm chapter. Flourish lists her current investments including Akua, Albo, Dolado, Heru, Kamino, Liquid, Minu, MoradaUno, Neon, Revena and Swap, with Dinie as an exit. She holds a bachelor's degree in accountancy from Northern Illinois University, an MBA from Cornell, and is an alumna of Stanford's VC Unlocked program.",
